import{_ as a,o as t,c as r,ao as i}from"./chunks/framework.D4Ibtiui.js";const l="/ImplicitGlobalGrid.jl/v0.17/assets/fig_parEff_HM3D_Julia_CUDA_all_Daint_extrapol.Bu3nZz0B.png",o="/ImplicitGlobalGrid.jl/v0.17/assets/implicit_global_grid.ZeOWNvLn.png",f=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":null}'),s={name:"overview.md"};function n(c,e,p,d,h,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="Overview" tabindex="-1">Overview <a class="header-anchor" href="#Overview" aria-label="Permalink to &quot;Overview {#Overview}&quot;">​</a></h1><p>ImplicitGlobalGrid renders the distributed parallelization of stencil-based GPU and CPU applications on a regular staggered grid almost trivial and enables close to ideal weak scaling of real-world applications on thousands of GPUs [<a href="https://pretalx.com/juliacon2019/talk/LGHLC3/" target="_blank" rel="noreferrer">1</a>, <a href="https://pasc19.pasc-conference.org/program/schedule/presentation/?id=msa218&amp;sess=sess144" target="_blank" rel="noreferrer">2</a>, <a href="https://www.youtube.com/watch?v=vPsfZUqI4_0" target="_blank" rel="noreferrer">3</a>]: <img src="'+l+'" alt="Weak scaling Piz Daint" style="display:block;margin:auto;width:100%;max-width:560px;"></p><p>ImplicitGlobalGrid relies on the Julia MPI wrapper (<a href="https://github.com/JuliaParallel/MPI.jl" target="_blank" rel="noreferrer">MPI.jl</a>) to perform halo updates close to hardware limit and leverages CUDA-aware or ROCm-aware MPI for GPU-applications. The communication can straightforwardly be hidden behind computation [<a href="https://pretalx.com/juliacon2019/talk/LGHLC3/" target="_blank" rel="noreferrer">1</a>, <a href="https://www.youtube.com/watch?v=vPsfZUqI4_0" target="_blank" rel="noreferrer">3</a>] (how this can be done automatically when using ParallelStencil.jl is shown in [<a href="https://www.youtube.com/watch?v=vPsfZUqI4_0" target="_blank" rel="noreferrer">3</a>]; a general approach particularly suited for CUDA C applications is explained in [<a href="https://on-demand.gputechconf.com/gtc/2019/video/_/S9368/" target="_blank" rel="noreferrer">4</a>]).</p><p>A particularity of ImplicitGlobalGrid is the automatic <em>implicit creation of the global computational grid</em> based on the number of processes the application is run with (and based on the process topology, which can be explicitly chosen by the user or automatically defined). As a consequence, the user only needs to write a code to solve his problem on one GPU/CPU (<em>local grid</em>); then, <strong>as little as three functions can be enough to transform a single GPU/CPU application into a massively scaling Multi-GPU/CPU application</strong>. See the <a href="/ImplicitGlobalGrid.jl/v0.17/examples/diffusion3D_multigpu_CuArrays_novis#example-50-lines">50-lines Multi-GPU example</a>. 1-D, 2-D and 3-D grids are supported. Here is a sketch of the global grid that results from running a 2-D solver with 4 processes (P1-P4) (a 2x2 process topology is created by default in this case): <img src="'+o+'" alt="Implicit global grid" style="display:block;margin:auto;width:100%;max-width:420px;"></p>',4)])])}const g=a(s,[["render",n]]);export{f as __pageData,g as default};
